     <script>
       function ConsentField() {
         return `
           <div class="form-field">
             <input id="terms" name="terms" type="checkbox" required />
             <div class="checkbox-copy">
               <label for="terms">I agree to the Terms of Use</label>
               <small>Required to continue.</small>
             </div>
           </div>
         `;
       }

       function App() {
         return `
           <section class="card" aria-labelledby="title">
             <h1 id="title">Consent form</h1>
             <p>Please review and confirm before submitting.</p>
             <form id="consent-form" novalidate>
               ${ConsentField()}
               <button type="submit">Submit</button>
               <div class="status" id="status" aria-live="polite"></div>
             </form>
           </section>
         `;
       }

       const app = document.getElementById("app");
       app.innerHTML = App();

       const form = document.getElementById("consent-form");
       const status = document.getElementById("status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         if (!form.checkValidity()) {
           form.reportValidity();
           status.textContent = "Please accept the terms to submit.";
           return;
         }

         status.textContent = "Thanks. Your consent has been recorded.";
       });
     </script>
   </body>
 </html>

')
